sp_widget.client_script:
api.controller = function($scope, $timeout) {
  var c = this;

  c.slides = $scope.data.slides;
  c.currentIndex = 0;

  var changing = false;

  c.setActive = function(index) {
    if (changing) return;
    changing = true;

    c.slides.forEach(function(slide, i) {
      slide.active = (i === index);
    });
    c.currentIndex = index;

    $timeout(function() {
      changing = false;
    }, 400);
  };

  c.setActive(0);
};

sp_widget.css:
.carousel-fullscreen {
  width: 100vw;
  margin-left: calc(-50vw + 50%);
  position: relative;
  background: #fff; /* sfondo bianco */
  text-align: center;
  padding: 20px 0; /* spazio sopra/sotto */
}

.carousel-fullscreen img {
  width: auto;
  max-width: 100%;
  max-height: 400px; /* più piccolo in altezza */
  object-fit: contain;
  display: block;
  margin: 0 auto;
  background-color: white;
}

/* Responsive: al di sotto di 768px */
@media (max-width: 768px) {
  .carousel-fullscreen img {
    max-height: 180px;
  }
}

/* ✅ Indicatori del carosello */
.carousel-indicators li {
  background-color: white;      /* cerchietti bianchi */
  border: 1px solid #000;       /* bordo nero per visibilità */
}

.carousel-indicators .active {
  background-color: black;      /* cerchietto attivo nero */
}

.toggle-animation {
  display: none !important;
}

.carousel-fullscreen a[href="#"] {
  cursor: default;
  pointer-events: none; /* Disattiva anche il click */
}

